(function(){
'use strict';
const KEY='ariellaChatState:v4';
function chat(){return document.getElementById('ariellaDesktopChat');}
function ensureBubbleStyles(){if(document.getElementById('ariella-chat-bubble-contrast-v2'))return;const s=document.createElement('style');s.id='ariella-chat-bubble-contrast-v2';s.textContent='.ac-row.user .ac-bubble{background:#d9f1f3!important;color:#17283f!important;border:1px solid #a9d6da!important;opacity:1!important}.ac-row.user{opacity:1!important}.ac-row.user .ac-bubble *{color:#17283f!important;opacity:1!important}';document.head.appendChild(s);}
function load(){try{return JSON.parse(localStorage.getItem(KEY)||'null')||{profile:{},history:[]};}catch(e){return {profile:{},history:[]};}}
function save(s){try{localStorage.setItem(KEY,JSON.stringify(s));}catch(e){}}
function add(who,text){ensureBubbleStyles();const c=chat(),box=c&&c.querySelector('#ariellaChatMessages');if(!box||!String(text||'').trim())return;const r=document.createElement('div');r.className='ac-row '+who;if(who==='bot'){const a=document.createElement('div');a.className='ac-mini-avatar';r.appendChild(a);}const b=document.createElement('div');b.className='ac-bubble';b.textContent=text;r.appendChild(b);box.appendChild(r);box.scrollTop=box.scrollHeight;}
function bot(text,s){add('bot',text);s.history=s.history||[];s.history.push({role:'assistant',content:text});save(s);}
function user(text,s){add('user',text);s.history=s.history||[];s.history.push({role:'user',content:text});save(s);}
function summary(p){const c=chat();if(!c)return;const months={january:'ינואר',february:'פברואר',march:'מרץ',april:'אפריל',may:'מאי',june:'יוני',july:'יולי',august:'אוגוסט',september:'ספטמבר',october:'אוקטובר',november:'נובמבר',december:'דצמבר'};const dest={montenegro:'מונטנגרו',greece:'יוון',italy:'איטליה',thailand:'תאילנד',albania:'אלבניה',croatia:'קרואטיה'};const tr=x=>{const k=String(x||'').trim().toLowerCase();return months[k]||dest[k]||x||''};const d=Array.isArray(p.destinations)?p.destinations.map(tr).join(', '):tr(p.destinations);const dates=p.departure_date&&p.return_date?p.departure_date+' – '+p.return_date:tr(p.outbound_month||p.return_month);const vals={destination:d,dates:dates,travelers:(p.adults||p.children||p.infants)?`${p.adults||0} מבוגרים${p.children?`, ${p.children} ילדים`:''}${p.infants?`, ${p.infants} תינוקות`:''}`:'',budget:p.budget_mode==='unlimited'?'ללא הגבלת תקציב':(p.budget_amount?`${p.budget_amount} ₪ לאדם`:''),flight:p.flight_preference==='direct'?'ישירה':(p.flight_preference||''),baggage:p.baggage||''};Object.keys(vals).forEach(k=>{const e=c.querySelector(`[data-summary-key="${k}"] span`);if(e)e.textContent=vals[k]||'עדיין לא צוין';});}
function isGreeting(t){return /^(היי+|הי+|שלום|בוקר טוב|ערב טוב|מה נשמע|hello|hi|hey)[!.? ]*$/i.test(t);}
function isNewTrip(t){return /(חופשה|נופש|טיול)\s+(חדשה|חדש)|לתכנן\s+(חופשה|נופש|טיול)\s+(חדש|חדשה)|חיפוש\s+חדש/.test(t);}
function changeField(t){if(!/(בעצם|תשנ|לשנות|שינוי|טעיתי|במקום|בכל זאת|מהתחלה|מחדש|לא,|לא )/.test(t))return '';if(/יעד|מקום|מדינה/.test(t))return 'destination';if(/תארי|מועד|חודש|יום/.test(t))return 'dates';if(/כבוד|טרולי|מזווד|תיק/.test(t))return 'baggage';if(/ישיר|קונקשן|טיסה/.test(t))return 'flight';if(/תקציב|מחיר/.test(t))return 'budget';if(/נוסע|ילד|מבוגר|תינוק/.test(t))return 'travelers';return 'general';}
function fieldPrompt(f){return {destination:'בטח 😊 לאיזה יעד תרצי לשנות?',dates:'בטח 😊 לאילו תאריכים או חודש תרצי לשנות?',baggage:'בטח 😊 איזו כבודה תרצי במקום?',flight:'בטח 😊 מה תרצי לשנות בטיסה — ישירה או קונקשן?',budget:'בטח 😊 מה התקציב החדש שתרצי שאקח בחשבון?',travelers:'בטח 😊 מי נוסע הפעם?'}[f]||'בטח 😊 מה תרצי לשנות?';}
function fallback(p){if((p.children||0)>0&&(!Array.isArray(p.child_ages)||p.child_ages.length<(p.children||0)))return 'בת כמה הילדה או בן כמה הילד שנוסעים איתך?';if(!p.flight_preference||!p.baggage)return 'מעולה 😊 ומה חשוב לכם מבחינת הטיסה? חשוב לכם לטוס ישיר, או שגם קונקשן יכול להתאים? ואיזו כבודה תצטרכו — תיק יד, טרולי או מזוודה?';if(!p.budget_mode&&p.budget_amount==null)return 'ולסיום, יש תקציב לאדם שתרצו שאשתדל לעמוד בו, או שאין מגבלת תקציב?';return 'קיבלתי 😊 אפשר להמשיך מכאן.';}
let busy=false;
async function send(raw){raw=String(raw||'').trim();if(!raw||busy)return;const c=chat(),input=c&&c.querySelector('#ariellaChatInput'),button=c&&c.querySelector('#ariellaChatSend');if(input)input.value='';let s=load();s.profile=s.profile||{};s.history=Array.isArray(s.history)?s.history:[];user(raw,s);const t=raw.toLowerCase();if(isGreeting(t)){bot('היי 😊 אני כאן. אפשר להמשיך בדיוק מאיפה שעצרנו, או לשנות כל פרט שתרצי.',s);return;}if(isNewTrip(t)){try{const a=JSON.parse(localStorage.getItem('ariellaChatTripsArchive')||'[]');a.push({profile:s.profile,history:s.history,saved_at:new Date().toISOString()});localStorage.setItem('ariellaChatTripsArchive',JSON.stringify(a.slice(-20)));}catch(e){}const keep={gender:s.profile.gender||s.profile.customer_gender,customer_gender:s.profile.customer_gender||s.profile.gender,first_name:s.profile.first_name,name:s.profile.name,departure_airports:['TLV']};s={profile:keep,history:[],flow:s.flow};save(s);const box=c&&c.querySelector('#ariellaChatMessages');if(box)box.innerHTML='';bot('בשמחה 😊 נתחיל חופשה חדשה, והחופשה הקודמת נשארת שמורה. מה מתכננים הפעם — חופשה רגילה, חופשת סקי או טיסת עסקים?',s);return;}const cf=changeField(t);if(cf&&(/^(מהתחלה|מחדש)$/.test(t))){bot('בשמחה 😊 תרצי להתחיל חופשה חדשה, או לשנות פרט בחופשה הנוכחית?',s);return;}if(cf&&cf!=='general'&&!/\b(ל|אל|ביולי|באוגוסט|באוקטובר|ישיר|קונקשן|טרולי|מזוודה)\b/.test(t)){s.profile._pending_change=cf;save(s);bot(fieldPrompt(cf),s);return;}busy=true;if(button)button.disabled=true;try{const prior=s.history.slice(0,-1).slice(-12);const r=await fetch('/api/ariella/chat',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({message:raw,history:prior,profile:s.profile})});const data=await r.json().catch(()=>({}));if(!r.ok||data.status!=='success'){bot(data.message||'יש כרגע תקלה זמנית. נסי שוב בעוד רגע.',s);return;}s.profile=data.profile||s.profile;delete s.profile._pending_change;summary(s.profile);const reply=String(data.reply||'').trim()||fallback(s.profile);bot(reply,s);}catch(e){bot('יש כרגע תקלה זמנית. נסי שוב בעוד רגע.',s);}finally{busy=false;if(button)button.disabled=false;if(input){input.focus();}}}
function intercept(e){const c=chat();if(!c)return;const input=c.querySelector('#ariellaChatInput'),button=c.querySelector('#ariellaChatSend');if(e.type==='click'&&e.target===button){e.preventDefault();e.stopImmediatePropagation();send(input.value);return;}if(e.type==='keydown'&&e.target===input&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.stopImmediatePropagation();send(input.value);}}
ensureBubbleStyles();document.addEventListener('click',intercept,true);document.addEventListener('keydown',intercept,true);
})();